namespace TakeOver.Help
{
    public static class HelpTopics
    {
        public sealed class Topic
        {
            public readonly string title, text, image;
            public Topic(string title, string text, string image = "") { this.title = title; this.text = text; this.image = image; }
        }
        public static readonly Topic[] Items = {
            new Topic("화면과 상단 메뉴", "홈에서는 사건 카드와 오늘의 진행 상황을 확인합니다. 지도·기업에서 회사를 찾고, 인물에서 관계와 기억을 살펴볼 수 있습니다.\n\n운영에서는 회사의 문서와 업무를 확인합니다. 사용 중인 기능이 궁금할 때는 이 도움말을 다시 열어주세요."),
            new Topic("자금과 자산", "보유자금은 지금 사용할 수 있는 내 돈입니다. 총 자산 가치는 현금과 보유 주식의 현재 평가액을 합친 값입니다.\n\n회사 재무 화면의 현금은 회사의 돈이므로 내 돈과 다릅니다. 주가가 바뀌면 보유 주식의 가치도 달라집니다."),
            new Topic("회사와 재무", "사업 소개와 함께 매출·순이익·현금·부채비율을 비교해보세요. 매출이 많아도 비용이 크거나 돈을 늦게 받으면 운영이 어려울 수 있습니다.\n\n주가 하나보다 회사가 어떻게 돈을 벌고 쓰는지 함께 살펴보는 것이 좋습니다.", "company"),
            new Topic("매수·추가 매수", "지도나 기업 목록에서 회사를 선택하고, 수량을 입력한 뒤 매수하기를 누르세요. 매수하면 현금이 줄고 보유 주식과 지분이 늘어납니다.\n\n필요한 대금과 남을 자금을 확인하세요. 자금이나 매수 가능한 주식이 부족하면 거래할 수 없습니다.", "buy"),
            new Topic("매도와 보유 지분", "회사 거래 화면에서 팔 수량을 입력하고 매도하기를 누르세요. 현금은 늘고 보유 지분은 줄어듭니다.\n\n일부 사건과 미션에는 지분 조건이 있습니다. 매도하기 전에 진행 중인 목표를 확인하세요.", "sell"),
            new Topic("하루와 행동 포인트", "만남을 시작하면 사건에 표시된 행동 포인트(AP)를 사용합니다. 카드나 설명을 읽는 것만으로는 소모되지 않습니다.\n\n하루 마감을 누르면 다음 날로 넘어가며 AP가 회복되고 주가와 사건이 갱신됩니다. 남은 미션과 처리할 일을 확인한 뒤 마감하세요.", "day"),
            new Topic("이벤트와 협상", "홈의 사건 카드에서 자세히 보기를 열고 내용을 확인한 뒤 만남을 시작하세요.\n\n대화에서는 계속으로 다음 말을 읽고, 선택지가 나오면 원하는 태도나 결정을 고릅니다. 선택은 자금·회사 상황·인물 관계에 영향을 줄 수 있으므로 비용이 있는 제안은 설명을 확인하세요.", "event"),
            new Topic("인물과 관계", "인물 화면에서 상대의 성향과 현재 관계를 확인할 수 있습니다. 같은 말도 상대와 상황에 따라 다르게 받아들여집니다.\n\n신뢰·존중·두려움·적대감·의존도·관심을 함께 살펴보세요. 수치가 높다고 언제나 좋은 관계를 뜻하지는 않습니다.", "profile"),
            new Topic("기억과 다음 만남", "선택과 행동은 인물의 기억에 남아 다음 만남에 영향을 줄 수 있습니다. 최근 기억을 읽으면 상대가 무엇을 중요하게 여기는지 알 수 있습니다.\n\n일부 기억은 시간이 지나며 흐려집니다. 관심을 표현하는 말과 실제 약속을 이행하는 행동은 서로 다르게 받아들여집니다.", "memory"),
            new Topic("경영 관련 제안", "지분과 회사 상황에 따라 경영 관련 제안을 받을 수 있습니다. 결정을 내리기 전에 바뀌는 내용과 비용을 살펴보세요.\n\n그린메일을 수락하면 보유 주식 전부를 웃돈을 받고 팔며, 해당 회사의 주식을 다시 살 수 없습니다. 구조조정 같은 제안은 회사와 직원에게 영향을 줄 수 있습니다."),
            new Topic("대화·스킵·주의사항", "계속은 다음 대사로, 스킵은 다음 선택이나 필수 조작 지점으로 이동합니다. 선택이 없는 장면은 대화만 이어집니다.\n\n타이틀의 튜토리얼 스킵은 기본 실습 결과를 반영한 상태로 시작합니다. 엔딩의 스킵은 다음 장면으로 이동합니다.\n\n진행은 자동 저장됩니다. 이어하기는 최근 저장을, 엔딩의 재도전은 준비 시점의 저장을 불러옵니다."),
            new Topic("메인 투자 목표·반복 만남", "게임을 진행하다 보면 스토리와 연계된 필수 미션이 좌측 상단에 갱신됩니다. 지정일까지 달성하지 못하면 회사 운영이 실패할 수 있으므로 주의하세요.\n\n필수 사건이 여러 개라면 모두 마쳐야 다음 일정을 진행할 수 있습니다. 일반 만남은 회사와 인물의 상황에 따라 다시 나타날 수 있습니다.")
        };
    }
}